/**
 * Neutralize comment terminators in untrusted text embedded in generated
 * comments: JS line terminators (\r, \n, U+2028, U+2029) end a `//`
 * comment, `-->` ends an HTML comment, and `*` + `/` ends a block comment.
 * Without this, a crafted name injects live code into a generated project.
 */
export function commentSafe(text) {
    return text
        .replace(/[\r\n\u2028\u2029]+/g, " ")
        .replace(/-->/g, "-- >")
        .replace(/\*\//g, "* /");
}
